import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, getJob, toJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function apiError(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = []; let size = 0;
  for await (const chunk of req) {
    const data = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    size += data.length;
    if (size > 1024 * 1024) throw new Error('too_large');
    chunks.push(data);
  }
  return Buffer.concat(chunks).toString('utf8');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') return apiError(res, 405, 'method_not_allowed', 'Method not allowed.');
    const row = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as { seen_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: row && Date.now() - row.seen_at <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const jobs = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all().map(toJob);
    return send(res, 200, { jobs });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: { field: string; message: string }[] = [];
    const contentType = req.headers['content-type'];
    if (!contentType || !/^application\/json(?:\s*;|\s*$)/i.test(contentType)) {
      return apiError(res, 400, 'invalid_request', 'Request must use Content-Type application/json.', [{ field: 'body', message: 'must use Content-Type application/json' }]);
    }
    let raw: string;
    try { raw = await readBody(req); } catch {
      return apiError(res, 400, 'invalid_request', 'Request body is invalid.', [{ field: 'body', message: 'must be valid JSON' }]);
    }
    let body: unknown;
    try { body = JSON.parse(raw); } catch {
      return apiError(res, 400, 'invalid_request', 'Request body is invalid.', [{ field: 'body', message: 'must be valid JSON' }]);
    }
    if (!body || typeof body !== 'object' || Array.isArray(body)) {
      return apiError(res, 400, 'invalid_request', 'Request body must be an object.', [{ field: 'body', message: 'must be an object' }]);
    }
    const value = body as Record<string, unknown>;
    for (const name of Object.keys(value)) if (!['input', 'steps', 'failAttempts'].includes(name)) fields.push({ field: name, message: 'is not allowed' });
    if (typeof value.input !== 'string') fields.push({ field: 'input', message: 'is required and must be a string' });
    else if (value.input.length < 1 || value.input.length > 1000 || value.input.trim().length === 0) fields.push({ field: 'input', message: 'must be 1–1000 characters and not only whitespace' });
    const steps = value.steps === undefined ? 5 : value.steps;
    const failAttempts = value.failAttempts === undefined ? 0 : value.failAttempts;
    if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
    if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
    const key = req.headers['idempotency-key'];
    if (key !== undefined && (typeof key !== 'string' || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({ field: 'Idempotency-Key', message: 'must contain 1–128 letters, numbers, underscores, or hyphens' });
    if (fields.length) return apiError(res, 400, 'invalid_request', 'Request validation failed.', fields);
    const input = value.input as string;
    const payload = JSON.stringify({ input, steps, failAttempts });
    if (key !== undefined) {
      const previous = db.prepare('SELECT payload, job_id FROM idempotency WHERE key=?').get(key as string) as { payload: string; job_id: string } | undefined;
      if (previous) {
        if (previous.payload !== payload) return apiError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        return send(res, 200, getJob(db, previous.job_id));
      }
    }
    const id = randomUUID(); const now = new Date().toISOString();
    db.exec('BEGIN IMMEDIATE');
    try {
      if (key !== undefined) {
        const prior = db.prepare('SELECT payload, job_id FROM idempotency WHERE key=?').get(key as string) as { payload: string; job_id: string } | undefined;
        if (prior) {
          db.exec('COMMIT');
          if (prior.payload !== payload) return apiError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
          return send(res, 200, getJob(db, prior.job_id));
        }
      }
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at)
        VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0)`).run(id, input, steps as number, failAttempts as number, now, now);
      if (key !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key as string, payload, id);
      db.exec('COMMIT');
    } catch (error) { db.exec('ROLLBACK'); throw error; }
    return send(res, 201, getJob(db, id));
  }
  if (pathname === '/api/jobs') return apiError(res, 405, 'method_not_allowed', 'Method not allowed.');
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (req.method !== 'GET') return apiError(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { return apiError(res, 404, 'not_found', 'Job not found.'); }
    const job = getJob(db, id);
    return job ? send(res, 200, job) : apiError(res, 404, 'not_found', 'Job not found.');
  }
  if (pathname === '/') return apiError(res, 405, 'method_not_allowed', 'Method not allowed.');
  return apiError(res, 404, 'not_found', 'Route not found.');
});
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown(): void { server.close(() => { db.close(); process.exit(0); }); }
process.on('SIGTERM', shutdown); process.on('SIGINT', shutdown);

