import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, toJob } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running job belongs to the previous worker instance and is retried from step zero.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, available_at=0, updated_at=? WHERE status='running'").run(new Date().toISOString());
const heartbeat = () => db.prepare('INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at').run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(() => { try { heartbeat(); } catch { /* database shutdown */ } }, 800);

async function processJob(row: any): Promise<void> {
  const job = toJob(row);
  const now = new Date().toISOString();
  db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(now, job.id);
  const attempt = job.attempts + 1;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(100);
    if (stopping) return;
    if (step === 1 && attempt <= job.failAttempts) {
      const updateTime = new Date().toISOString();
      if (attempt >= 3) {
        db.prepare("UPDATE jobs SET status='failed', progress_completed=0, error='transient failure', result_output=NULL, updated_at=? WHERE id=?").run(updateTime, job.id);
      } else {
        db.prepare("UPDATE jobs SET status='queued', progress_completed=0, error=NULL, result_output=NULL, available_at=?, updated_at=? WHERE id=?").run(Date.now() + 500, updateTime, job.id);
      }
      return;
    }
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step, new Date().toISOString(), job.id);
  }
  db.prepare("UPDATE jobs SET status='completed', result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'").run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now());
    if (!row) { await sleep(100); continue; }
    await processJob(row);
  }
} finally {
  clearInterval(heartbeatTimer);
  db.close();
}

