10	    label { display: grid; gap: .25rem; } input, button { font: inherit; padding: .5rem; }
11	    [role="alert"] { color: #a21d25; min-height: 1.25em; }
12	    #job-list { list-style: none; padding: 0; display: grid; gap: .75rem; }
13	    [data-testid="job-item"] { border: 1px solid #ccd3dc; border-radius: .5rem; padding: .8rem; }
14	    .meta { color: #536170; font-size: .9rem; }
15	  </style>
16	</head>
17	<body>
18	  <h1>Job tracker</h1>
19	  <form data-testid="job-form">
20	    <label>Input <input data-testid="job-input" name="input" required maxlength="1000"></label>
21	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
22	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
23	    <button data-testid="job-submit" type="submit">Submit job</button>
24	    <div data-testid="form-error" role="alert"></div>
25	  </form>
26	  <h2>Jobs</h2>
27	  <ul data-testid="job-list" id="job-list"></ul>
28	  <script>
29	    const form = document.querySelector('[data-testid="job-form"]');
30	    const errorRegion = document.querySelector('[data-testid="form-error"]');
31	    const list = document.querySelector('[data-testid="job-list"]');
32	    const esc = (value) => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
33	    function render(jobs) {
34	      list.innerHTML = jobs.map(job => `<li data-testid="job-item" data-job-id="${esc(job.id)}"><strong>${esc(job.input)}</strong>
35	        <div>Status: <span data-testid="job-status">${esc(job.status)}</span></div>
36	        <div>Progress: <span data-testid="job-progress">${job.progress.completed}/${job.progress.total}</span></div>
37	        <div>Result: <span data-testid="job-result">${esc(job.result?.output ?? job.error ?? '')}</span></div>
38	        <div class="meta">Attempts: ${job.attempts}</div></li>`).join('');
39	    }
40	    async function refresh() {
41	      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); } catch { /* retry on next poll */ }
42	    }
43	    form.addEventListener('submit', async event => {
44	      event.preventDefault(); errorRegion.textContent = '';
45	      const data = new FormData(form);
46	      const payload = { input: data.get('input'), steps: Number(data.get('steps')), failAttempts: Number(data.get('failAttempts')) };
47	      try {
48	        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
49	        const body = await response.json();
50	        if (!response.ok) {
51	          const details = body.error?.fields?.map(item => `${item.field}: ${item.message}`).join('; ');
52	          errorRegion.textContent = details || body.error?.message || 'Unable to submit job';
53	        } else { form.elements.input.value = ''; await refresh(); }
54	      } catch { errorRegion.textContent = 'Unable to submit job'; }
55	    });
56	    refresh(); setInterval(refresh, 500);
57	  </script>
58	</body>
59	</html>
